-- Social kit schema (generated by tools/build-schema.mjs from StitchedUp migrations 001-247).
-- Apply to a NEW, EMPTY Supabase project. Server-side service-role access only:
-- RLS is enabled on every table with no policies, so anon/authenticated keys see nothing.
SET search_path = public;

-- Trigger functions

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$function$;

CREATE OR REPLACE FUNCTION public.update_social_posts_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_social_week_plans_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_social_week_plan_items_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

-- Minimal customers (only first/last name are read by the social code)

CREATE TABLE public.customers (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    business_id uuid,
    first_name text,
    last_name text,
    created_at timestamp with time zone DEFAULT now()
);
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;

-- Tables, indexes, constraints, triggers

SET lock_timeout = 0;

SET idle_in_transaction_session_timeout = 0;

SET transaction_timeout = 0;

SET client_encoding = 'UTF8';

SET standard_conforming_strings = on;

SET check_function_bodies = false;

SET xmloption = content;

SET client_min_messages = warning;

SET row_security = off;

SET default_tablespace = '';

SET default_table_access_method = heap;

CREATE TABLE public.social_week_plan_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    business_id uuid NOT NULL,
    sort_order integer NOT NULL,
    target_date date NOT NULL,
    post_type text NOT NULL,
    subtype_id text,
    intent_chip text,
    topic text NOT NULL,
    user_brief text,
    job_id uuid,
    platforms jsonb DEFAULT '[]'::jsonb NOT NULL,
    caption text,
    status text DEFAULT 'planned'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    generation_id uuid,
    generation_status text DEFAULT 'not_started'::text NOT NULL,
    generation_error text,
    variant_previews jsonb,
    generation_started_at timestamp with time zone,
    generation_completed_at timestamp with time zone,
    selected_variant_id uuid,
    review_status text DEFAULT 'needs_selection'::text NOT NULL,
    hybrid_render_id uuid,
    scheduled_social_post_id uuid,
    approved_at timestamp with time zone,
    skipped_at timestamp with time zone,
    variant_previews_previous jsonb,
    CONSTRAINT social_week_plan_items_generation_status_check CHECK ((generation_status = ANY (ARRAY['not_started'::text, 'queued'::text, 'generating'::text, 'generated'::text, 'failed'::text]))),
    CONSTRAINT social_week_plan_items_review_status_check CHECK ((review_status = ANY (ARRAY['needs_selection'::text, 'selected'::text, 'approved'::text, 'scheduled'::text, 'skipped'::text]))),
    CONSTRAINT social_week_plan_items_status_check CHECK ((status = 'planned'::text))
);

COMMENT ON TABLE public.social_week_plan_items IS 'Individual planned posts within a social_week_plans row.';

COMMENT ON COLUMN public.social_week_plan_items.generation_status IS 'Per-item AI Designed generation lifecycle (separate from item.status planned).';

COMMENT ON COLUMN public.social_week_plan_items.selected_variant_id IS 'UUID of chosen variant_previews[].id — selection is free, no regen.';

COMMENT ON COLUMN public.social_week_plan_items.review_status IS 'Production desk lifecycle: needs_selection → selected → approved → scheduled (or skipped).';

COMMENT ON COLUMN public.social_week_plan_items.hybrid_render_id IS 'Library row after passThroughVisual finalization (0 credits).';

COMMENT ON COLUMN public.social_week_plan_items.scheduled_social_post_id IS 'Immutable scheduled post snapshot; planner edits do not alter this row.';

COMMENT ON COLUMN public.social_week_plan_items.variant_previews_previous IS 'Previous variant set after Quick Change (one-level history V1).';

CREATE TABLE public.ai_image_scene_options (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    purpose text NOT NULL,
    scene_label text NOT NULL,
    scene_prompt_fragment text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL
);

COMMENT ON TABLE public.ai_image_scene_options IS 'Preset scene options for social post AI image generation (Step 4 guided flow).';

CREATE TABLE public.ai_usage_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    user_id uuid,
    feature text NOT NULL,
    provider text NOT NULL,
    model text,
    usage_type text NOT NULL,
    input_tokens bigint,
    output_tokens bigint,
    cached_input_tokens bigint,
    units numeric,
    unit_name text,
    request_id text,
    provider_request_id text,
    related_entity_type text,
    related_entity_id uuid,
    provider_cost_usd numeric,
    fx_rate_usd_to_aud numeric,
    provider_cost_aud numeric,
    customer_credits_charged numeric,
    customer_amount_aud numeric,
    status text NOT NULL,
    cost_quality text DEFAULT 'unknown'::text NOT NULL,
    is_refunded boolean DEFAULT false NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    pricing_version text,
    error_code text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_usage_events_cost_quality_chk CHECK ((cost_quality = ANY (ARRAY['actual'::text, 'estimated'::text, 'unknown'::text]))),
    CONSTRAINT ai_usage_events_status_chk CHECK ((status = ANY (ARRAY['success'::text, 'failed'::text, 'partial'::text, 'cancelled'::text])))
);

COMMENT ON TABLE public.ai_usage_events IS 'Provider AI COGS events snapshotted at call time. Not customer billing. Metering starts at migration deploy. Do not store prompts or PII.';

CREATE TABLE public.business_brand_assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    asset_type text DEFAULT 'logo'::text NOT NULL,
    storage_path text NOT NULL,
    public_url text,
    display_name text NOT NULL,
    variant_type text DEFAULT 'other'::text NOT NULL,
    is_primary boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_brand_assets_type_check CHECK ((asset_type = 'logo'::text)),
    CONSTRAINT business_brand_assets_variant_check CHECK ((variant_type = ANY (ARRAY['primary'::text, 'light'::text, 'dark'::text, 'icon'::text, 'horizontal'::text, 'stacked'::text, 'other'::text])))
);

COMMENT ON TABLE public.business_brand_assets IS 'Approved brand assets (logos). Exactly one logo per business is primary; businesses.logo_url mirrors that primary.';

