    CONSTRAINT businesses_subscription_status_check CHECK ((subscription_status = ANY (ARRAY['pending'::text, 'processing'::text, 'trialing'::text, 'trial_expired'::text, 'active'::text, 'past_due'::text, 'refunded'::text, 'cancelled'::text]))),
