COMMENT ON COLUMN public.businesses.subscription_tier IS 'StitchedUp commercial plan: core or pro.';

COMMENT ON COLUMN public.businesses.google_calendar_sync_enabled IS 'Whether to auto-sync jobs to Google Calendar';

COMMENT ON COLUMN public.businesses.brand_color IS 'Primary brand color used on quotes, invoices, emails (hex format)';

COMMENT ON COLUMN public.businesses.brand_text_color IS 'Text color for buttons/CTAs using brand color (auto-calculated)';

COMMENT ON COLUMN public.businesses.subscription_started_at IS 'When the business started their paid subscription';

COMMENT ON COLUMN public.businesses.refund_eligible_until IS '30 days after subscription_started_at - full refund available until this date';

COMMENT ON COLUMN public.businesses.subscription_status IS 'active = paying customer, refunded = got full refund, cancelled = stopped subscription';

COMMENT ON COLUMN public.businesses.monthly_price IS 'Monthly subscription price in dollars (197, 297, or 497)';

COMMENT ON COLUMN public.businesses.airwallex_subscription_id IS 'Airwallex subscription ID for reference';

COMMENT ON COLUMN public.businesses.airwallex_customer_id IS 'Airwallex customer ID for reference';

COMMENT ON COLUMN public.businesses.ai_booking_enabled IS 'When true, the AI receptionist can check availability and book jobs via Vapi tools.';

COMMENT ON COLUMN public.businesses.ai_booking_hours IS 'Working hours for AI booking availability — day keys with {start,end} HH:MM or null if closed.';

COMMENT ON COLUMN public.businesses.timezone IS 'IANA timezone for job scheduling and calendar display (e.g. Australia/Sydney).';

COMMENT ON COLUMN public.businesses.airwallex_billing_customer_id IS 'Airwallex Billing Customer ID (bcus_*) for subscription billing — separate from PA customer.';

COMMENT ON COLUMN public.businesses.subscription_monthly_price IS 'Monthly subscription price in cents (e.g. 29700 = $297/month AUD)';

COMMENT ON COLUMN public.businesses.social_logo_corner IS 'Default corner for logo compositing on AI Full Post images.';

COMMENT ON COLUMN public.businesses.social_compose_last_category IS 'Last PostCategoryId selected in /social Create Step 1 (default tab).';

COMMENT ON COLUMN public.businesses.social_compose_last_subtype IS 'Last PostSubtypeId selected in /social Create Step 1.';

COMMENT ON COLUMN public.businesses.trial_start IS 'When the 30-day card-free product trial began (post-onboarding).';

COMMENT ON COLUMN public.businesses.trial_end IS 'When trialing access ends if no paid subscription.';

COMMENT ON COLUMN public.businesses.past_due_at IS 'First transition to past_due — used for 14-day grace before lockout.';

COMMENT ON COLUMN public.businesses.subscription_access_until IS 'Paid access end (cancel-at-period-end or period end from Airwallex).';

COMMENT ON COLUMN public.businesses.airwallex_payment_source_id IS 'Latest Airwallex Payment Source (psrc_*) for card-on-file before subscription or synced from checkout.';

COMMENT ON COLUMN public.businesses.arrival_tracking_enabled IS 'Opt-in: tradies can send customers a short-lived on-my-way tracking link via SMS.';

COMMENT ON COLUMN public.businesses.push_notifications_enabled IS 'When false, server-side push sends are skipped for all users in this business.';

COMMENT ON COLUMN public.businesses.onboarding_completed_at IS 'When the owner finished or skipped the last onboarding wizard step. NULL = still required.';

COMMENT ON COLUMN public.businesses.airwallex_tradiespost_billing_customer_id IS 'Airwallex billing customer (bcus_*) on the TradiesPost Airwallex account (AIRWALLEX_TRADIESPOST_*).';

COMMENT ON COLUMN public.businesses.airwallex_tradiespost_customer_id IS 'Airwallex PA customer (cus_*) on the TradiesPost Airwallex account (AIRWALLEX_TRADIESPOST_*).';

COMMENT ON COLUMN public.businesses.acquisition_product IS 'Original product at signup (tradiespost | stitchedup). Set once; null for legacy rows.';

COMMENT ON COLUMN public.businesses.stripe_account_type IS 'express = new Connect account via Account Links; standard = existing Stripe account via OAuth';

COMMENT ON COLUMN public.businesses.primary_trade_slug IS 'Canonical primary trade for Trade Library, recommendations, and AI context.';

COMMENT ON COLUMN public.businesses.app_access_scope IS 'Preferred/home gated scope (last campaign). Use app_access_scopes for allowlist union.';

COMMENT ON COLUMN public.businesses.missed_call_phone_mode IS 'existing_forward = keep carrier number and forward misses; stitchedup_number = owned StitchedUp line; demo = trial on the shared platform demo number';

COMMENT ON COLUMN public.businesses.existing_business_number IS 'Tradie-owned mobile/business number (E.164 or local AU) used in existing_forward mode — not the Twilio messaging number';

COMMENT ON COLUMN public.businesses.ai_receptionist_live_enabled IS 'When true, inbound calls on the StitchedUp business number are answered by the AI voice receptionist (Vapi). Publish/setup status is independent.';

COMMENT ON COLUMN public.businesses.missed_call_ack_audio_path IS 'Storage object path in missed-call-ack bucket for the cached acknowledgement MP3.';

COMMENT ON COLUMN public.businesses.missed_call_ack_audio_hash IS 'Deterministic cache key (voice + copy + version). Skip ElevenLabs when unchanged.';

COMMENT ON COLUMN public.businesses.missed_call_ack_message IS 'Owner-edited missed-call voice acknowledgement. Null or empty uses the canonical default.';

COMMENT ON COLUMN public.businesses.missed_call_ack_mode IS 'ai_voice = generated receptionist clip; recorded_voice = owner-recorded WAV.';

COMMENT ON COLUMN public.businesses.app_access_scopes IS 'Stacked gated campaign scopes. Empty = full product. Prefer app_access_scope for home path.';

COMMENT ON COLUMN public.businesses.missed_call_onboarding_completed_at IS 'Set when the communications first-run missed-call wizard is finished.';

COMMENT ON COLUMN public.businesses.notification_email IS 'Optional Missed Call AI / lead alert destination. Does not change login email.';

COMMENT ON COLUMN public.businesses.included_phone_number_count IS 'Count of numbers whose Twilio rent is waived. Communications entry = 1. Never cleared on upgrade.';

COMMENT ON COLUMN public.businesses.tiktok_access_token IS 'TikTok user access token (24h). Refreshed via tiktok_refresh_token (365d, rotates).';

CREATE TABLE public.google_business_performance_daily (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    gmb_location_id text NOT NULL,
    metric_date date NOT NULL,
    business_impressions_desktop_maps integer,
    business_impressions_mobile_maps integer,
    business_impressions_desktop_search integer,
    business_impressions_mobile_search integer,
    website_clicks integer,
    call_clicks integer,
    business_direction_requests integer,
    business_conversations integer,
    business_bookings integer,
    business_food_orders integer,
    business_food_menu_clicks integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.google_business_performance_daily IS 'Cached GBP daily metrics from Business Profile Performance API. Cron writes via service_role.';

CREATE TABLE public.google_business_search_keywords (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    gmb_location_id text NOT NULL,
    month date NOT NULL,
    keyword text NOT NULL,
    impressions integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.google_business_search_keywords IS 'Cached GBP monthly search-keyword impressions. month is first-of-month.';

CREATE TABLE public.hybrid_social_renders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    job_id uuid,
    preset text NOT NULL,
    platform text NOT NULL,
    photo_source text,
    photo_url text,
    content jsonb DEFAULT '{}'::jsonb NOT NULL,
    result_url text,
    status text DEFAULT 'processing'::text NOT NULL,
    error_message text,
    used_free_trial boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hybrid_social_renders_platform_check CHECK ((platform = ANY (ARRAY['instagram'::text, 'facebook'::text, 'gmb'::text]))),
    CONSTRAINT hybrid_social_renders_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'completed'::text, 'failed'::text])))
);

COMMENT ON TABLE public.hybrid_social_renders IS 'Hybrid social image renders (infographic/scene SVG+resvg) — charged via render_credits.';

CREATE TABLE public.job_photos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    business_id uuid NOT NULL,
    url text NOT NULL,
    webp_url text,
    file_size integer,
    stage_at_upload text,
    trade_type text,
    suburb text,
    caption text,
    uploaded_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT job_photos_stage_at_upload_check CHECK ((stage_at_upload = ANY (ARRAY['in_progress'::text, 'job_done'::text, 'quote'::text])))
);

CREATE TABLE public.jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    customer_id uuid,
    title text NOT NULL,
    site_address text,
    stage text DEFAULT 'new_lead'::text NOT NULL,
    assigned_to uuid,
    callout_fee_applied boolean DEFAULT false,
    payment_path text,
    notes text,
    cancellation_reason text,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    payment_structure text DEFAULT 'single'::text,
    milestone_count integer DEFAULT 0,
    total_collected numeric DEFAULT 0,
    total_outstanding numeric DEFAULT 0,
    scheduled_start timestamp with time zone,
    scheduled_end timestamp with time zone,
    scheduled_date date,
    duration_hours numeric DEFAULT 1,
    calendar_color text,
    google_calendar_event_id text,
    is_recurring boolean DEFAULT false,
    recurring_frequency text,
    labour_rate_override numeric,
    labour_hours_actual numeric DEFAULT 0,
    materials_cost_actual numeric DEFAULT 0,
    subcontractor_cost numeric DEFAULT 0,
    other_cost numeric DEFAULT 0,
    total_revenue numeric DEFAULT 0,
    total_cost numeric DEFAULT 0,
    gross_profit numeric DEFAULT 0,
    gross_margin numeric DEFAULT 0,
    net_profit numeric DEFAULT 0,
    net_margin numeric DEFAULT 0,
    stripe_fees numeric DEFAULT 0,
    platform_fees numeric DEFAULT 0,
    costing_notes text,
    job_category text,
    site_latitude numeric,
    site_longitude numeric,
    site_suburb text,
    site_state text,
    site_postcode text,
    urgency text DEFAULT 'unknown'::text NOT NULL,
    emergency_callback_required boolean DEFAULT false NOT NULL,
    CONSTRAINT jobs_payment_path_check CHECK ((payment_path = ANY (ARRAY['stripe'::text, 'direct'::text, 'split'::text, 'milestone'::text]))),
    CONSTRAINT jobs_payment_structure_check CHECK ((payment_structure = ANY (ARRAY['single'::text, 'deposit'::text, 'milestone'::text]))),
    CONSTRAINT jobs_recurring_frequency_check CHECK ((recurring_frequency = ANY (ARRAY['weekly'::text, 'fortnightly'::text, 'monthly'::text]))),
    CONSTRAINT jobs_stage_check CHECK ((stage = ANY (ARRAY['new_lead'::text, 'contacted'::text, 'quote_sent'::text, 'quote_accepted'::text, 'in_progress'::text, 'job_done'::text, 'invoice_sent'::text, 'paid'::text, 'cancelled'::text]))),
    CONSTRAINT jobs_urgency_check CHECK ((urgency = ANY (ARRAY['emergency'::text, 'urgent'::text, 'normal'::text, 'unknown'::text])))
);

COMMENT ON COLUMN public.jobs.scheduled_start IS 'Start date and time of scheduled job (AEST)';

COMMENT ON COLUMN public.jobs.scheduled_end IS 'End date and time of scheduled job (AEST)';

COMMENT ON COLUMN public.jobs.scheduled_date IS 'Date portion of scheduled_start for easier querying';

COMMENT ON COLUMN public.jobs.duration_hours IS 'Duration in hours (e.g. 0.5 for 30min, 1.5 for 90min)';

COMMENT ON COLUMN public.jobs.google_calendar_event_id IS 'Google Calendar event ID for synced jobs';

COMMENT ON COLUMN public.jobs.urgency IS 'Call/chat urgency from AI structured data. emergency = live safety issue.';

COMMENT ON COLUMN public.jobs.emergency_callback_required IS 'True when urgent callback follow-up is required (e.g. failed emergency transfer).';

CREATE TABLE public.meta_connect_pending_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    user_id uuid NOT NULL,
    platform text NOT NULL,
    pages jsonb DEFAULT '[]'::jsonb NOT NULL,
    demo boolean DEFAULT false NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT meta_connect_pending_sessions_platform_check CHECK ((platform = ANY (ARRAY['facebook'::text, 'instagram'::text])))
);

CREATE TABLE public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    user_id uuid,
    type text NOT NULL,
    title text NOT NULL,
    message text,
    read boolean DEFAULT false,
    job_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    reference_id text,
    url text
);

CREATE TABLE public.render_credit_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    event_type text NOT NULL,
    credits integer NOT NULL,
    render_id uuid,
    pack_key text,
    airwallex_ref text,
    amount_aud numeric(10,2),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT render_credit_events_event_type_check CHECK ((event_type = ANY (ARRAY['purchase'::text, 'used'::text, 'refund'::text]))),
    CONSTRAINT render_credit_events_pack_key_check CHECK (((pack_key IS NULL) OR (pack_key = ANY (ARRAY['10'::text, '25'::text, '60'::text]))))
);

COMMENT ON TABLE public.render_credit_events IS 'Ledger for render credit purchases, usage, and refunds.';

COMMENT ON COLUMN public.render_credit_events.render_id IS 'Optional correlation id (before_after_renders.id or hybrid_social_renders.id).';

CREATE TABLE public.render_credits (
    business_id uuid NOT NULL,
    credits_remaining integer DEFAULT 0 NOT NULL,
    free_trial_used boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT render_credits_credits_remaining_check CHECK ((credits_remaining >= 0))
);

COMMENT ON TABLE public.render_credits IS 'Before & After render credit balance per business — separate from subscription and social credits.';

CREATE TABLE public.social_credit_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    event_type text DEFAULT 'image_generated'::text NOT NULL,
    template_style integer,
    post_type text,
    platform text,
    job_id uuid,
    orshot_template_id text DEFAULT '14154'::text,
    orshot_render_url text,
    credits_used integer DEFAULT 1 NOT NULL,
    cost_usd numeric(10,4) DEFAULT 0.01,
    is_test boolean DEFAULT false
);

COMMENT ON TABLE public.social_credit_events IS 'Orshot render credit log — one row per image_generated event.';

CREATE TABLE public.social_media_assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    job_id uuid,
    media_type text DEFAULT 'video'::text NOT NULL,
    status text DEFAULT 'uploading'::text NOT NULL,
    original_url text,
    processed_url text,
    thumbnail_url text,
    storage_path text,
    thumbnail_path text,
    duration_seconds numeric,
    mime_type text,
    file_size_bytes bigint,
    caption text,
    about_text text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_storage_path text,
    processing_status text DEFAULT 'none'::text NOT NULL,
    branding_config jsonb,
    CONSTRAINT social_media_assets_media_type_check CHECK ((media_type = 'video'::text)),
    CONSTRAINT social_media_assets_processing_status_check CHECK ((processing_status = ANY (ARRAY['none'::text, 'processing'::text, 'processed'::text, 'processing_failed'::text]))),
    CONSTRAINT social_media_assets_status_check CHECK ((status = ANY (ARRAY['uploading'::text, 'ready'::text, 'failed'::text, 'deleted'::text])))
);

COMMENT ON TABLE public.social_media_assets IS 'Customer-uploaded social media (video V1). Generated images remain in hybrid_social_renders.';

COMMENT ON COLUMN public.social_media_assets.processed_storage_path IS 'Storage path for branded MP4 output (social-posts bucket). Original storage_path unchanged.';

COMMENT ON COLUMN public.social_media_assets.processing_status IS 'Branding pipeline state — separate from upload status (uploading/ready/failed/deleted).';

COMMENT ON COLUMN public.social_media_assets.branding_config IS 'Last successful branding settings (logo, positions, overlay text) for edit/reprocess UX.';

CREATE TABLE public.social_posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    job_id uuid,
    status text DEFAULT 'draft'::text NOT NULL,
    caption text,
    platforms text[] DEFAULT ARRAY['instagram'::text] NOT NULL,
    photo_urls text[],
    processed_photo_urls jsonb,
    scheduled_for timestamp with time zone,
    posted_at timestamp with time zone,
    facebook_post_id text,
    instagram_post_id text,
    gmb_post_id text,
    linkedin_post_id text,
    facebook_error text,
    instagram_error text,
    gmb_error text,
    linkedin_error text,
    job_suburb text,
    job_state text,
    trade_type text,
    ai_generated boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    media_type text DEFAULT 'image'::text,
    video_url text,
    video_duration_seconds numeric,
    uploaded_media_urls text[],
    overlay_style_override text,
    platform_captions jsonb DEFAULT '{}'::jsonb,
    posted_manually boolean DEFAULT false NOT NULL,
    compose_category text,
    compose_subtype text,
    publishing_mode text DEFAULT 'automatic'::text NOT NULL,
    week_plan_item_id uuid,
    tiktok_publish_id text,
    tiktok_post_id text,
    tiktok_error text,
    tiktok_status text,
    tiktok_settings jsonb,
    CONSTRAINT social_posts_media_type_check CHECK ((media_type = ANY (ARRAY['image'::text, 'video'::text, 'carousel'::text]))),
    CONSTRAINT social_posts_overlay_style_override_check CHECK ((overlay_style_override = ANY (ARRAY['bottom_bar'::text, 'corner'::text, 'top_banner'::text, 'minimal_tag'::text, 'frame'::text, 'none'::text]))),
    CONSTRAINT social_posts_publishing_mode_check CHECK ((publishing_mode = ANY (ARRAY['automatic'::text, 'manual'::text]))),
    CONSTRAINT social_posts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'posted'::text, 'failed'::text, 'cancelled'::text])))
);

COMMENT ON COLUMN public.social_posts.media_type IS 'image | video | carousel';

COMMENT ON COLUMN public.social_posts.video_url IS 'Direct URL to video file in Supabase storage';

COMMENT ON COLUMN public.social_posts.video_duration_seconds IS 'Validated duration in seconds (max 30)';

COMMENT ON COLUMN public.social_posts.uploaded_media_urls IS 'Media uploaded directly (not from job photos)';

COMMENT ON COLUMN public.social_posts.platform_captions IS 'Per-platform caption map, e.g. {"instagram":"...","facebook":"...","gmb":"..."}. Legacy caption column remains fallback until Stage 2/3.';

COMMENT ON COLUMN public.social_posts.posted_manually IS 'True when the tradie marked the post as published manually (no platform API call).';

COMMENT ON COLUMN public.social_posts.compose_category IS 'Optional PostCategoryId when post was created from template compose.';

COMMENT ON COLUMN public.social_posts.compose_subtype IS 'Optional PostSubtypeId when post was created from template compose.';

COMMENT ON COLUMN public.social_posts.publishing_mode IS 'automatic = cron/API publish; manual = calendar reminder only, never auto-published.';

COMMENT ON COLUMN public.social_posts.week_plan_item_id IS 'Planner item that created this calendar row; survives planner reset for history lookup.';

COMMENT ON COLUMN public.social_posts.tiktok_status IS 'Last TikTok publish status: PROCESSING_UPLOAD | PROCESSING_DOWNLOAD | SEND_TO_USER_INBOX | PUBLISH_COMPLETE | FAILED';

COMMENT ON COLUMN public.social_posts.tiktok_settings IS 'User-chosen TikTok post settings: { privacyLevel, disableComment, disableDuet, disableStitch, brandOrganic, brandedContent }';

CREATE TABLE public.social_style_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    trade_category text NOT NULL,
    orshot_template_id text NOT NULL,
    orshot_page numeric,
    thumbnail_url text,
    sort_order integer DEFAULT 0,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    fields jsonb DEFAULT '[{"key": "headline", "type": "text", "label": "Business name", "source": "businessName", "maxLength": 60}, {"key": "description", "type": "text", "label": "Description", "source": "jobDescription", "maxLength": 120}, {"key": "tagline", "type": "text", "label": "Tagline", "source": "tagline", "maxLength": 50}, {"key": "website", "type": "text", "label": "Website", "source": "website"}, {"key": "social", "type": "text", "label": "Social handle", "source": "socialHandle"}, {"key": "service1", "type": "text", "label": "Service 1", "maxLength": 40}, {"key": "service2", "type": "text", "label": "Service 2", "maxLength": 40}, {"key": "phone", "type": "text", "label": "Phone", "source": "businessPhone"}, {"key": "photo", "type": "photo", "label": "Photo"}]'::jsonb
);

COMMENT ON TABLE public.social_style_templates IS 'Orshot social post style library — trade_category filters Step 3 tabs.';

CREATE TABLE public.social_video_processing_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asset_id uuid NOT NULL,
    business_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    logo_choice text DEFAULT 'none'::text NOT NULL,
    logo_asset_id uuid,
    logo_position text,
    logo_size text,
    overlay_text text,
    text_position text,
    output_storage_path text NOT NULL,
    output_version integer DEFAULT 1 NOT NULL,
    previous_processed_path text,
    error_code text,
    error_message text,
    claimed_at timestamp with time zone,
    worker_id text,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT social_video_processing_jobs_logo_choice_check CHECK ((logo_choice = ANY (ARRAY['none'::text, 'primary'::text, 'asset'::text]))),
    CONSTRAINT social_video_processing_jobs_logo_position_check CHECK (((logo_position IS NULL) OR (logo_position = ANY (ARRAY['top_left'::text, 'top_right'::text, 'bottom_left'::text, 'bottom_right'::text])))),
    CONSTRAINT social_video_processing_jobs_logo_size_check CHECK (((logo_size IS NULL) OR (logo_size = ANY (ARRAY['small'::text, 'medium'::text, 'large'::text])))),
    CONSTRAINT social_video_processing_jobs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT social_video_processing_jobs_text_position_check CHECK (((text_position IS NULL) OR (text_position = ANY (ARRAY['top'::text, 'center'::text, 'bottom'::text]))))
);

COMMENT ON TABLE public.social_video_processing_jobs IS 'Async queue for FFmpeg video branding. Worker claims pending rows via service role.';

CREATE TABLE public.social_week_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    week_start_date date NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    post_count_target integer NOT NULL,
    wizard_answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by_user_id uuid,
    approved_by_user_id uuid,
    approved_at timestamp with time zone,
    generation_started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    generation_status text DEFAULT 'not_started'::text NOT NULL,
    CONSTRAINT social_week_plans_generation_status_check CHECK ((generation_status = ANY (ARRAY['not_started'::text, 'queued'::text, 'generating'::text, 'ready'::text, 'partial_failed'::text, 'failed'::text]))),
    CONSTRAINT social_week_plans_post_count_target_check CHECK (((post_count_target >= 1) AND (post_count_target <= 7))),
    CONSTRAINT social_week_plans_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'plan_approved'::text, 'archived'::text])))
);

COMMENT ON TABLE public.social_week_plans IS 'Build My Week — weekly social content plans (Phase A: text-only, no image generation).';

COMMENT ON COLUMN public.social_week_plans.generation_status IS 'Async whole-week generation lifecycle (separate from plan.status).';

CREATE TABLE public.users (
    id uuid NOT NULL,
    business_id uuid,
    email text NOT NULL,
    full_name text,
    phone text,
    role text NOT NULL,
    permissions jsonb DEFAULT '{"can_view_crm": false, "can_send_quotes": false, "can_mark_job_done": false, "can_send_invoices": false, "can_upload_photos": false}'::jsonb,
    avatar_url text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    admin_product_access text[] DEFAULT '{}'::text[] NOT NULL,
    internal_staff_status text,
    CONSTRAINT users_internal_staff_status_check CHECK (((internal_staff_status IS NULL) OR (internal_staff_status = ANY (ARRAY['pending'::text, 'active'::text, 'disabled'::text])))),
    CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['super_admin'::text, 'support_admin'::text, 'owner'::text, 'team_member'::text, 'va'::text, 'accountant'::text])))
);

COMMENT ON COLUMN public.users.admin_product_access IS 'Platform staff product scope: stitchedup, tradiespost. Empty for customer users. super_admin ignores (full access).';

COMMENT ON COLUMN public.users.internal_staff_status IS 'Internal staff lifecycle: pending (pre-accept), active, disabled. NULL for customer users.';

CREATE TABLE public.webhook_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid,
    source text DEFAULT 'native'::text NOT NULL,
    event_type text NOT NULL,
    status text DEFAULT 'success'::text NOT NULL,
    payload jsonb,
    error_message text,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT webhook_logs_status_check CHECK ((status = ANY (ARRAY['success'::text, 'error'::text])))
);

COMMENT ON TABLE public.webhook_logs IS 'Raw third-party webhook payloads (may contain call transcripts + customer PII). RLS enabled with no policies — service-role only.';

