-- RPCs (service role only)

CREATE OR REPLACE FUNCTION public.claim_next_social_week_plan_item()
 RETURNS SETOF social_week_plan_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  candidate_id uuid;
  claimed social_week_plan_items;
  now_ts timestamptz := now();
BEGIN
  SELECT i.id INTO candidate_id
  FROM social_week_plan_items i
  WHERE i.generation_status = 'queued'
    AND NOT EXISTS (
      SELECT 1
      FROM social_week_plan_items g
      WHERE g.plan_id = i.plan_id
        AND g.generation_status = 'generating'
    )
  ORDER BY i.created_at ASC
  LIMIT 1
  FOR UPDATE SKIP LOCKED;

  IF candidate_id IS NULL THEN
    RETURN;
  END IF;

  UPDATE social_week_plan_items
  SET
    generation_status = 'generating',
    generation_started_at = now_ts,
    generation_error = NULL,
    updated_at = now_ts
  WHERE id = candidate_id
    AND generation_status = 'queued'
  RETURNING * INTO claimed;

  IF claimed.id IS NULL THEN
    RETURN;
  END IF;

  UPDATE social_week_plans
  SET
    generation_status = 'generating',
    updated_at = now_ts
  WHERE id = claimed.plan_id
    AND business_id = claimed.business_id
    AND generation_status IN ('queued', 'generating');

  RETURN NEXT claimed;
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.claim_next_social_week_plan_item() FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.claim_next_social_week_plan_item() TO service_role;

